            expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", "
                    + "org.springframework.samples.petclinic.rest.function.common.FiscalYear"
                    + ".yy(owner.getRegistrationDate())))")
    @Mapping(target = "fiscalYear",
